mapper.select:
SELECT


FROM TB_ITINERARY i

WHERE i.user_id = #{userId}

AND i.status = 'ACTIVE'

ORDER BY i.created_at DESC

LIMIT #{limit}
OFFSET #{offset}

SELECT


FROM TB_ITINERARY_BOOKMARK myBookmark

INNER JOIN TB_ITINERARY i
ON i.itinerary_id = myBookmark.itinerary_id

WHERE myBookmark.user_id = #{userId}

AND i.status = 'ACTIVE'

AND (
i.user_id = #{userId}
OR i.visibility = 'PUBLIC'
)

ORDER BY myBookmark.created_at DESC

LIMIT #{limit}
OFFSET #{offset}

SELECT


FROM TB_ITINERARY_LIKE myLike

INNER JOIN TB_ITINERARY i
ON i.itinerary_id = myLike.itinerary_id

WHERE myLike.user_id = #{userId}

AND i.status = 'ACTIVE'

AND i.visibility = 'PUBLIC'

AND i.user_id != #{userId}

ORDER BY myLike.created_at DESC

LIMIT #{limit}
OFFSET #{offset}

SELECT


FROM TB_ITINERARY i

WHERE i.user_id = #{userId}

AND i.status = 'ACTIVE'

AND i.visibility = 'PUBLIC'

ORDER BY i.created_at DESC

LIMIT #{limit}
OFFSET #{offset}

SELECT


FROM TB_ITINERARY_LIKE profileLiked

INNER JOIN TB_ITINERARY i
ON i.itinerary_id = profileLiked.itinerary_id

WHERE profileLiked.user_id = #{userId}

AND i.status = 'ACTIVE'

AND i.visibility = 'PUBLIC'

AND i.user_id != #{userId}

ORDER BY profileLiked.created_at DESC

LIMIT #{limit}
OFFSET #{offset}

SELECT


FROM TB_ITINERARY_BOOKMARK profileSaved

INNER JOIN TB_ITINERARY i
ON i.itinerary_id = profileSaved.itinerary_id

WHERE profileSaved.user_id = #{userId}

AND i.status = 'ACTIVE'

AND i.visibility = 'PUBLIC'

ORDER BY profileSaved.created_at DESC

LIMIT #{limit}
OFFSET #{offset}

